INSERT INTO faq (`id`,`type`,`name`,`pid`,`disporder`,`description`,`created_at`,`updated_at`,`is_active`,`views_count`,`icon_class`) VALUES ('5','item','How do I clear my cookies?','2','1','<div class=\"faq-content\">\r\n    <p>You may clear all your cookies by clicking <a href=\"/logout.php\" class=\"text-primary fw-semibold\">here</a>. If you return to the main index page via the link provided and you are still logged in, you may have to remove your cookies manually.</p>\r\n    \r\n    <div class=\"mt-4\">\r\n        <h6 class=\"fw-bold mb-3\"><i class=\"bi bi-windows me-2\"></i>In Internet Explorer:</h6>\r\n        <ol class=\"ps-3\">\r\n            <li>Click the \"Tools\" menu</li>\r\n            <li>Select \"Internet Options\" from the menu</li>\r\n            <li>Click \"Delete Cookies\" on the General tab</li>\r\n        </ol>\r\n    </div>\r\n    \r\n    <div class=\"mt-4\">\r\n        <h6 class=\"fw-bold mb-3\"><i class=\"bi bi-firefox me-2\"></i>In Mozilla Firefox:</h6>\r\n        <ol class=\"ps-3\">\r\n            <li>Click the \"Tools\" menu</li>\r\n            <li>Select \"Options\" from the menu</li>\r\n            <li>Select \"Privacy & Security\" on the left</li>\r\n            <li>Find \"Cookies and Site Data\" and click \"Clear Data\"</li>\r\n        </ol>\r\n    </div>\r\n    \r\n    <div class=\"alert alert-info mt-4\">\r\n        <i class=\"bi bi-info-circle me-2\"></i>\r\n        <strong>Tip:</strong> Your cookies should now be removed. You may want to restart the browser and revisit the tracker to be sure.\r\n    </div>\r\n</div>','2026-01-04 15:51:12','2026-03-13 15:07:55','1','19','bi-cookie');
INSERT INTO faq (`id`,`type`,`name`,`pid`,`disporder`,`description`,`created_at`,`updated_at`,`is_active`,`views_count`,`icon_class`) VALUES ('6','item','Why should I register?','1','2','<div class=\"faq-content\">\r\n    <p>Registration is free and provides you with full access to all features of our platform:</p>\r\n    \r\n    <div class=\"row mt-3\">\r\n        <div class=\"col-md-6\">\r\n            <div class=\"d-flex align-items-start mb-3\">\r\n                <div class=\"icon-wrapper bg-primary bg-opacity-10 rounded-circle p-2 me-3\">\r\n                    <i class=\"bi bi-shield-check text-primary\"></i>\r\n                </div>\r\n                <div>\r\n                    <h6 class=\"fw-bold mb-1\">Enhanced Security</h6>\r\n                    <p class=\"small text-muted mb-0\">Secure account with personalized settings</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n        <div class=\"col-md-6\">\r\n            <div class=\"d-flex align-items-start mb-3\">\r\n                <div class=\"icon-wrapper bg-success bg-opacity-10 rounded-circle p-2 me-3\">\r\n                    <i class=\"bi bi-cloud-arrow-down text-success\"></i>\r\n                </div>\r\n                <div>\r\n                    <h6 class=\"fw-bold mb-1\">Full Access</h6>\r\n                    <p class=\"small text-muted mb-0\">Download torrents and access all content</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    \r\n    <div class=\"benefits-list mt-4\">\r\n        <h6 class=\"fw-bold mb-3\">Additional Benefits:</h6>\r\n        <ul class=\"list-unstyled\">\r\n            <li class=\"mb-2\"><i class=\"bi bi-check-circle text-success me-2\"></i> Post comments and reviews</li>\r\n            <li class=\"mb-2\"><i class=\"bi bi-check-circle text-success me-2\"></i> Invite friends to join</li>\r\n            <li class=\"mb-2\"><i class=\"bi bi-check-circle text-success me-2\"></i> Create and manage watchlists</li>\r\n            <li class=\"mb-2\"><i class=\"bi bi-check-circle text-success me-2\"></i> Receive notifications</li>\r\n            <li class=\"mb-2\"><i class=\"bi bi-check-circle text-success me-2\"></i> Earn bonus points</li>\r\n        </ul>\r\n    </div>\r\n    \r\n    <div class=\"mt-4\">\r\n        <a href=\"/signup.php\" class=\"btn btn-primary\">\r\n            <i class=\"bi bi-person-plus me-2\"></i>Register Now\r\n        </a>\r\n    </div>\r\n</div>','2026-01-04 15:51:12','2026-04-05 01:13:37','1','12','bi-person-plus');
INSERT INTO faq (`id`,`type`,`name`,`pid`,`disporder`,`description`,`created_at`,`updated_at`,`is_active`,`views_count`,`icon_class`) VALUES ('7','item','I lost my password, what can I do?','1','3','<div class=\"faq-content\">\r\n    <p>If you\'ve forgotten your password, follow these simple steps to recover it:</p>\r\n    \r\n    <div class=\"steps-container mt-4\">\r\n        <div class=\"step-item mb-4\">\r\n            <div class=\"step-number d-inline-flex align-items-center justify-content-center rounded-circle bg-primary text-white me-3\" style=\"width: 30px; height: 30px;\">1</div>\r\n            <div class=\"step-content d-inline-block\">\r\n                <h6 class=\"fw-bold mb-1\">Visit Password Recovery Page</h6>\r\n                <p class=\"text-muted small mb-0\">Click on the <a href=\"/recover.php\" class=\"fw-semibold\">\'Forgot Password\'</a> link</p>\r\n            </div>\r\n        </div>\r\n        \r\n        <div class=\"step-item mb-4\">\r\n            <div class=\"step-number d-inline-flex align-items-center justify-content-center rounded-circle bg-primary text-white me-3\" style=\"width: 30px; height: 30px;\">2</div>\r\n            <div class=\"step-content d-inline-block\">\r\n                <h6 class=\"fw-bold mb-1\">Enter Your Email</h6>\r\n                <p class=\"text-muted small mb-0\">Provide the email address associated with your account</p>\r\n            </div>\r\n        </div>\r\n        \r\n        <div class=\"step-item mb-4\">\r\n            <div class=\"step-number d-inline-flex align-items-center justify-content-center rounded-circle bg-primary text-white me-3\" style=\"width: 30px; height: 30px;\">3</div>\r\n            <div class=\"step-content d-inline-block\">\r\n                <h6 class=\"fw-bold mb-1\">Check Your Email</h6>\r\n                <p class=\"text-muted small mb-0\">Look for password reset instructions in your inbox</p>\r\n            </div>\r\n        </div>\r\n        \r\n        <div class=\"step-item\">\r\n            <div class=\"step-number d-inline-flex align-items-center justify-content-center rounded-circle bg-primary text-white me-3\" style=\"width: 30px; height: 30px;\">4</div>\r\n            <div class=\"step-content d-inline-block\">\r\n                <h6 class=\"fw-bold mb-1\">Create New Password</h6>\r\n                <p class=\"text-muted small mb-0\">Follow the link and set a new secure password</p>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    \r\n    <div class=\"alert alert-warning mt-4\">\r\n        <i class=\"bi bi-exclamation-triangle me-2\"></i>\r\n        <strong>Need Help?</strong> If you encounter any issues, please contact our support team at <a href=\"mailto:support@seedboxworld.biz\" class=\"fw-semibold\">support@seedboxworld.biz</a>\r\n    </div>\r\n</div>','2026-01-04 15:51:12','2026-04-05 01:13:37','1','12','bi-key');
INSERT INTO faq (`id`,`type`,`name`,`pid`,`disporder`,`description`,`created_at`,`updated_at`,`is_active`,`views_count`,`icon_class`) VALUES ('8','item','How can I change my profile information?','1','4','<div class=\"faq-content\">\r\n    <p>Keeping your profile information up-to-date is important for account security and communication.</p>\r\n    \r\n    <div class=\"mt-4\">\r\n        <h6 class=\"fw-bold mb-3\">To edit your profile:</h6>\r\n        <ol class=\"ps-3\">\r\n            <li class=\"mb-2\">Log into your account</li>\r\n            <li class=\"mb-2\">Click on your username in the top navigation</li>\r\n            <li class=\"mb-2\">Select \"User Control Panel\" or \"Profile Settings\"</li>\r\n            <li class=\"mb-2\">Make the desired changes to your information</li>\r\n            <li>Click \"Save Changes\" to update your profile</li>\r\n        </ol>\r\n    </div>\r\n    \r\n    <div class=\"mt-4\">\r\n        <a href=\"/usercp.php\" class=\"btn btn-outline-primary\">\r\n            <i class=\"bi bi-gear me-2\"></i>Go to Profile Settings\r\n        </a>\r\n    </div>\r\n    \r\n    <div class=\"alert alert-info mt-4\">\r\n        <i class=\"bi bi-info-circle me-2\"></i>\r\n        <strong>Note:</strong> Your username cannot be changed after registration. In exceptional circumstances, contact support for assistance.\r\n    </div>\r\n</div>','2026-01-04 15:51:12','2026-04-05 01:13:37','1','12','bi-person-gear');
INSERT INTO faq (`id`,`type`,`name`,`pid`,`disporder`,`description`,`created_at`,`updated_at`,`is_active`,`views_count`,`icon_class`) VALUES ('9','item','How can we help support your site?','2','1','<div class=\"faq-content\">\r\n    <p>We appreciate your support! There are several ways you can help us continue providing excellent service:</p>\r\n    \r\n    <div class=\"row mt-4\">\r\n        <div class=\"col-lg-6 mb-4\">\r\n            <div class=\"card border-0 shadow-sm h-100\">\r\n                <div class=\"card-body text-center p-4\">\r\n                    <div class=\"icon-wrapper bg-danger bg-opacity-10 rounded-circle p-3 mx-auto mb-3\" style=\"width: 70px; height: 70px;\">\r\n                        <i class=\"bi bi-heart-fill text-danger fs-3\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold mb-3\">Make a Donation</h5>\r\n                    <p class=\"text-muted mb-4\">Your donations help cover server costs and development expenses.</p>\r\n                    <a href=\"https://www.seedboxworld.biz/donate.php\" class=\"btn btn-danger\">\r\n                        <i class=\"bi bi-coin me-2\"></i>Donate Now\r\n                    </a>\r\n                </div>\r\n            </div>\r\n        </div>\r\n        \r\n        <div class=\"col-lg-6 mb-4\">\r\n            <div class=\"card border-0 shadow-sm h-100\">\r\n                <div class=\"card-body text-center p-4\">\r\n                    <div class=\"icon-wrapper bg-success bg-opacity-10 rounded-circle p-3 mx-auto mb-3\" style=\"width: 70px; height: 70px;\">\r\n                        <i class=\"bi bi-share-fill text-success fs-3\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold mb-3\">Share & Invite</h5>\r\n                    <p class=\"text-muted mb-4\">Invite friends and share content to grow our community.</p>\r\n                    <a href=\"/invite.php\" class=\"btn btn-success\">\r\n                        <i class=\"bi bi-person-plus me-2\"></i>Invite Friends\r\n                    </a>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    \r\n    <div class=\"mt-4\">\r\n        <h6 class=\"fw-bold mb-3\">Other Ways to Help:</h6>\r\n        <ul class=\"list-unstyled\">\r\n            <li class=\"mb-2\"><i class=\"bi bi-chat-dots text-info me-2\"></i> Provide feedback and suggestions</li>\r\n            <li class=\"mb-2\"><i class=\"bi bi-arrow-up-circle text-warning me-2\"></i> Seed torrents to help others</li>\r\n            <li class=\"mb-2\"><i class=\"bi bi-flag text-primary me-2\"></i> Report issues and broken links</li>\r\n            <li><i class=\"bi bi-star text-warning me-2\"></i> Rate and review content</li>\r\n        </ul>\r\n    </div>\r\n</div>','2026-01-04 15:51:12','2026-03-13 15:07:55','1','19','bi-heart');
INSERT INTO faq (`id`,`type`,`name`,`pid`,`disporder`,`description`,`created_at`,`updated_at`,`is_active`,`views_count`,`icon_class`) VALUES ('10','item','How do I submit feedback or suggestions?','2','2','<div class=\"faq-content\">\r\n    <p>We value your feedback and are always looking for ways to improve our platform.</p>\r\n    \r\n    <div class=\"mt-4\">\r\n        <h6 class=\"fw-bold mb-3\">Submit Your Feedback:</h6>\r\n        \r\n        <div class=\"feedback-options\">\r\n            <div class=\"option-item p-3 border rounded-3 mb-3\">\r\n                <div class=\"d-flex align-items-center\">\r\n                    <div class=\"icon-wrapper bg-info bg-opacity-10 rounded-circle p-2 me-3\">\r\n                        <i class=\"bi bi-envelope text-info\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <h6 class=\"fw-bold mb-1\">Contact Form</h6>\r\n                        <p class=\"small text-muted mb-0\">Use our official contact form for detailed feedback</p>\r\n                    </div>\r\n                    <div class=\"ms-auto\">\r\n                        <a href=\"https://www.seedboxworld.biz/contactstaff.php\" class=\"btn btn-sm btn-outline-info\">\r\n                            Go to Form\r\n                        </a>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"option-item p-3 border rounded-3 mb-3\">\r\n                <div class=\"d-flex align-items-center\">\r\n                    <div class=\"icon-wrapper bg-primary bg-opacity-10 rounded-circle p-2 me-3\">\r\n                        <i class=\"bi bi-chat-left-text text-primary\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <h6 class=\"fw-bold mb-1\">Forum Discussion</h6>\r\n                        <p class=\"small text-muted mb-0\">Start a discussion in our community forum</p>\r\n                    </div>\r\n                    <div class=\"ms-auto\">\r\n                        <a href=\"/forum.php\" class=\"btn btn-sm btn-outline-primary\">\r\n                            Visit Forum\r\n                        </a>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"option-item p-3 border rounded-3\">\r\n                <div class=\"d-flex align-items-center\">\r\n                    <div class=\"icon-wrapper bg-success bg-opacity-10 rounded-circle p-2 me-3\">\r\n                        <i class=\"bi bi-bug text-success\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <h6 class=\"fw-bold mb-1\">Bug Reports</h6>\r\n                        <p class=\"small text-muted mb-0\">Report technical issues and bugs</p>\r\n                    </div>\r\n                    <div class=\"ms-auto\">\r\n                        <a href=\"mailto:bugs@seedboxworld.biz\" class=\"btn btn-sm btn-outline-success\">\r\n                            Email Bugs\r\n                        </a>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    \r\n    <div class=\"alert alert-success mt-4\">\r\n        <i class=\"bi bi-lightbulb me-2\"></i>\r\n        <strong>Pro Tip:</strong> When submitting feedback, be as specific as possible. Include screenshots and step-by-step instructions if reporting an issue.\r\n    </div>\r\n</div>','2026-01-04 15:51:12','2026-03-13 15:07:55','1','19','bi-chat-left-dots');
INSERT INTO faq (`id`,`type`,`name`,`pid`,`disporder`,`description`,`created_at`,`updated_at`,`is_active`,`views_count`,`icon_class`) VALUES ('11','item','Will my account be deleted for inactivity?','1','5','<div class=\"faq-content\">\r\n    <p>We understand that users may take breaks from using our service. Here\'s our policy on account inactivity:</p>\r\n    \r\n    <div class=\"policy-details mt-4\">\r\n        <div class=\"d-flex align-items-start mb-4\">\r\n            <div class=\"icon-wrapper bg-success bg-opacity-10 rounded-circle p-2 me-3\">\r\n                <i class=\"bi bi-check-circle-fill text-success\"></i>\r\n            </div>\r\n            <div>\r\n                <h6 class=\"fw-bold mb-2\">No Automatic Deletion</h6>\r\n                <p class=\"text-muted mb-0\">We do not automatically delete accounts due to inactivity or lack of visits.</p>\r\n            </div>\r\n        </div>\r\n        \r\n        <div class=\"d-flex align-items-start mb-4\">\r\n            <div class=\"icon-wrapper bg-info bg-opacity-10 rounded-circle p-2 me-3\">\r\n                <i class=\"bi bi-shield-check text-info\"></i>\r\n            </div>\r\n            <div>\r\n                <h6 class=\"fw-bold mb-2\">Security Retention</h6>\r\n                <p class=\"text-muted mb-0\">Accounts and emails are retained for security purposes and fraud prevention.</p>\r\n            </div>\r\n        </div>\r\n        \r\n        <div class=\"d-flex align-items-start\">\r\n            <div class=\"icon-wrapper bg-warning bg-opacity-10 rounded-circle p-2 me-3\">\r\n                <i class=\"bi bi-clock-history text-warning\"></i>\r\n            </div>\r\n            <div>\r\n                <h6 class=\"fw-bold mb-2\">Long-term Storage</h6>\r\n                <p class=\"text-muted mb-0\">Your account data is preserved indefinitely unless you request deletion.</p>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    \r\n    <div class=\"mt-4\">\r\n        <h6 class=\"fw-bold mb-3\">Account Management Options:</h6>\r\n        <div class=\"row g-3\">\r\n            <div class=\"col-md-6\">\r\n                <div class=\"card border-0 bg-light\">\r\n                    <div class=\"card-body\">\r\n                        <h6 class=\"fw-bold\">Reactivate Account</h6>\r\n                        <p class=\"small text-muted mb-0\">Simply log in to reactivate your account</p>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-md-6\">\r\n                <div class=\"card border-0 bg-light\">\r\n                    <div class=\"card-body\">\r\n                        <h6 class=\"fw-bold\">Request Deletion</h6>\r\n                        <p class=\"small text-muted mb-0\">Contact support for account deletion requests</p>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    \r\n    <div class=\"alert alert-info mt-4\">\r\n        <i class=\"bi bi-info-circle me-2\"></i>\r\n        <strong>Note:</strong> For security reasons, accounts with verified purchases or transactions are never automatically purged from our system.\r\n    </div>\r\n</div>','2026-01-04 15:51:12','2026-04-05 01:13:37','1','12','bi-person-x');
