INSERT INTO faq (`id`,`type`,`name`,`pid`,`disporder`,`description`,`created_at`,`updated_at`,`is_active`,`views_count`,`icon_class`) VALUES ('14','item','How can I update my payment method?','12','1','<div class=\"faq-content\"><p>You can update your payment method in your account settings. Navigate to <strong>Billing & Payments</strong> and add a new method or edit the existing one.</p></div>','2026-01-26 13:40:46','2026-03-15 14:24:01','1','4','bi-wallet2');
INSERT INTO faq (`id`,`type`,`name`,`pid`,`disporder`,`description`,`created_at`,`updated_at`,`is_active`,`views_count`,`icon_class`) VALUES ('15','item','Can I get a refund?','12','2','<div class=\"faq-content\"><p>Refunds are considered on a case-by-case basis. Please contact support at <a href=\"mailto:support@example.com\">support@example.com</a> for assistance.</p></div>','2026-01-26 13:40:46','2026-03-15 14:24:01','1','4','bi-arrow-counterclockwise');
INSERT INTO faq (`id`,`type`,`name`,`pid`,`disporder`,`description`,`created_at`,`updated_at`,`is_active`,`views_count`,`icon_class`) VALUES ('16','item','How do I change my password?','13','1','<div class=\"faq-content\"><p>To change your password, go to <strong>Profile Settings</strong> > <strong>Security</strong> and select <strong>Change Password</strong>. Make sure to choose a strong, unique password.</p></div>','2026-01-26 13:40:46','2026-04-05 01:03:11','1','4','bi-key');
INSERT INTO faq (`id`,`type`,`name`,`pid`,`disporder`,`description`,`created_at`,`updated_at`,`is_active`,`views_count`,`icon_class`) VALUES ('17','item','How is my data protected?','13','2','<div class=\"faq-content\"><p>We use industry-standard encryption and secure servers to protect your personal data. For more details, visit our <a href=\"/privacy.php\">Privacy Policy</a>.</p></div>','2026-01-26 13:40:46','2026-04-05 01:03:11','1','4','bi-shield-check');
INSERT INTO faq (`id`,`type`,`name`,`pid`,`disporder`,`description`,`created_at`,`updated_at`,`is_active`,`views_count`,`icon_class`) VALUES ('18','item','Can I change my username?','1','6','<div class=\"faq-content\"><p>Usernames are permanent once registered. If you need a change due to special circumstances, contact <a href=\"mailto:support@example.com\">support</a>.</p></div>','2026-01-26 13:42:40','2026-04-05 01:13:37','1','6','bi-person-badge');
INSERT INTO faq (`id`,`type`,`name`,`pid`,`disporder`,`description`,`created_at`,`updated_at`,`is_active`,`views_count`,`icon_class`) VALUES ('19','item','How do I delete my account?','1','7','<div class=\"faq-content\"><p>To delete your account, contact support via <a href=\"mailto:support@example.com\">email</a>. Account deletion is irreversible.</p></div>','2026-01-26 13:42:40','2026-04-05 01:13:37','1','6','bi-person-x-fill');
INSERT INTO faq (`id`,`type`,`name`,`pid`,`disporder`,`description`,`created_at`,`updated_at`,`is_active`,`views_count`,`icon_class`) VALUES ('20','item','What browsers are supported?','2','3','<div class=\"faq-content\"><p>Our platform supports the latest versions of Chrome, Firefox, Edge, and Safari. Older browsers may not display all features correctly.</p></div>','2026-01-26 13:42:40','2026-03-13 15:07:55','1','3','bi-browser-chrome');
INSERT INTO faq (`id`,`type`,`name`,`pid`,`disporder`,`description`,`created_at`,`updated_at`,`is_active`,`views_count`,`icon_class`) VALUES ('21','item','Do you offer a mobile app?','2','4','<div class=\"faq-content\"><p>We currently do not have a dedicated mobile app, but our website is fully responsive and works on all modern mobile devices.</p></div>','2026-01-26 13:42:40','2026-03-13 15:07:55','1','3','bi-phone');
INSERT INTO faq (`id`,`type`,`name`,`pid`,`disporder`,`description`,`created_at`,`updated_at`,`is_active`,`views_count`,`icon_class`) VALUES ('22','item','How do I start seeding?','3','4','<div class=\"faq-content\"><p>After downloading a torrent, keep your client running with the file in the same location to continue seeding and earn ratio credit.</p></div>','2026-01-26 13:42:40','2026-03-13 15:07:58','1','2','bi-arrow-up-circle');
INSERT INTO faq (`id`,`type`,`name`,`pid`,`disporder`,`description`,`created_at`,`updated_at`,`is_active`,`views_count`,`icon_class`) VALUES ('23','item','What is a magnet link?','3','5','<div class=\"faq-content\"><p>A magnet link is a URL containing all the information needed to download a torrent without needing the .torrent file. Click it to open in your torrent client.</p></div>','2026-01-26 13:42:40','2026-03-13 15:07:58','1','2','bi-link-45deg');
INSERT INTO faq (`id`,`type`,`name`,`pid`,`disporder`,`description`,`created_at`,`updated_at`,`is_active`,`views_count`,`icon_class`) VALUES ('24','item','Why is my download slow?','4','5','<div class=\"faq-content\"><p>Download speed depends on your connection, the number of seeders, and network traffic. Ensure your client is properly configured and ports are open.</p></div>','2026-01-26 13:42:40','2026-04-05 01:23:06','1','5','bi-speedometer2');
INSERT INTO faq (`id`,`type`,`name`,`pid`,`disporder`,`description`,`created_at`,`updated_at`,`is_active`,`views_count`,`icon_class`) VALUES ('25','item','How do I report a bug?','4','6','<div class=\"faq-content\"><p>Report bugs via <a href=\"/contactstaff.php\">contact form</a> or email <a href=\"mailto:bugs@example.com\">bugs@example.com</a>. Provide detailed steps and screenshots if possible.</p></div>','2026-01-26 13:42:40','2026-04-05 01:23:06','1','5','bi-bug');
INSERT INTO faq (`id`,`type`,`name`,`pid`,`disporder`,`description`,`created_at`,`updated_at`,`is_active`,`views_count`,`icon_class`) VALUES ('26','item','What payment methods are accepted?','12','3','<div class=\"faq-content\"><p>We accept credit/debit cards, PayPal, and select cryptocurrencies. Check your billing page for full options.</p></div>','2026-01-26 13:42:40','2026-03-15 14:24:01','1','4','bi-credit-card-2-back');
INSERT INTO faq (`id`,`type`,`name`,`pid`,`disporder`,`description`,`created_at`,`updated_at`,`is_active`,`views_count`,`icon_class`) VALUES ('27','item','How do I view my billing history?','12','4','<div class=\"faq-content\"><p>Go to <strong>Account Settings</strong> > <strong>Billing History</strong> to see past invoices and payments.</p></div>','2026-01-26 13:42:40','2026-03-15 14:24:01','1','4','bi-journal-text');
INSERT INTO faq (`id`,`type`,`name`,`pid`,`disporder`,`description`,`created_at`,`updated_at`,`is_active`,`views_count`,`icon_class`) VALUES ('28','item','How do I enable two-factor authentication?','13','3','<div class=\"faq-content\"><p>Navigate to <strong>Profile Settings</strong> > <strong>Security</strong> > <strong>Two-Factor Authentication</strong> and follow the instructions to set up 2FA.</p></div>','2026-01-26 13:42:40','2026-04-05 01:03:11','1','4','bi-shield-lock-fill');
INSERT INTO faq (`id`,`type`,`name`,`pid`,`disporder`,`description`,`created_at`,`updated_at`,`is_active`,`views_count`,`icon_class`) VALUES ('29','item','How do I report a security issue?','13','4','<div class=\"faq-content\"><p>If you discover a security vulnerability, please email <a href=\"mailto:security@example.com\">security@example.com</a> immediately. We take all reports seriously.</p></div>','2026-01-26 13:42:40','2026-04-05 01:03:11','1','4','bi-exclamation-triangle-fill');
INSERT INTO rules (`id`,`title`,`text`,`usergroups`,`category`,`priority`,`is_active`,`icon`,`created_at`,`updated_at`,`last_updated_by`) VALUES ('9','Bonus Points & Economy System','[list]\r\n[*]Earn points by seeding torrents (1 point per 3 hours)\r\n[*]Points can be traded for upload credit (100 points = 1 GB)\r\n[*]Invite friends to earn bonus points (500 points per active user)\r\n[*]Donate to receive [img]/pic/star.gif[/img] status and bonus\r\n[*]Participate in community events for extra rewards\r\n[*]No point trading or selling between users\r\n[/list]\r\n\r\n[h2]Point Earning Rates[/h2]\r\n[table]\r\n[tr]\r\n[th]Seed Time[/th]\r\n[th]Points Earned[/th]\r\n[/tr]\r\n[tr]\r\n[td]1 hour[/td]\r\n[td]0.33[/td]\r\n[/tr]\r\n[tr]\r\n[td]24 hours[/td]\r\n[td]8[/td]\r\n[/tr]\r\n[tr]\r\n[td]1 week[/td]\r\n[td]56[/td]\r\n[/tr]\r\n[/table]','[0]','economy','60','1','fa-coins','2026-01-04 21:38:06','2026-01-04 21:38:06',NULL);
INSERT INTO rules (`id`,`title`,`text`,`usergroups`,`category`,`priority`,`is_active`,`icon`,`created_at`,`updated_at`,`last_updated_by`) VALUES ('10','Invitation System Rules','[list]\r\n[*]Invites are earned based on user class and activity\r\n[*]You are responsible for users you invite\r\n[*]Invited users must follow all site rules\r\n[*]Invite abuse results in loss of invitation privileges\r\n[*]Do not sell or trade invitations\r\n[*]Report inactive invites for recycling\r\n[*]New users have 7 days to activate account\r\n[/list]\r\n\r\n[h2]Invite Allocation[/h2]\r\n[b]Power User:[/b] 1 invite per month\r\n[b]VIP:[/b] 3 invites per month\r\n[b]Uploader:[/b] 5 invites per month\r\n[b]Moderator:[/b] Unlimited invites','[1][2][3][4][5][6][7]','account','85','1','fa-user-plus','2026-01-04 21:38:06','2026-01-04 21:38:06',NULL);
INSERT INTO rules (`id`,`title`,`text`,`usergroups`,`category`,`priority`,`is_active`,`icon`,`created_at`,`updated_at`,`last_updated_by`) VALUES ('11','DMCA & Legal Compliance','[list]\r\n[*]We comply with all legitimate DMCA takedown requests\r\n[*]Uploaded content must not violate copyright laws\r\n[*]No discussion of bypassing copyright protection\r\n[*]Report infringing content using report button\r\n[*]Repeat infringers will have accounts terminated\r\n[*]Keep backup of your data - we\'re not responsible for loss\r\n[/list]\r\n\r\n[alert type=\"danger\"]\r\n[b]Legal Notice:[/b] This site does not host any files - we only provide torrent files. All content is user-uploaded.\r\n[/alert]','[0]','legal','99','1','fa-balance-scale','2026-01-04 21:38:06','2026-01-04 21:38:06',NULL);
INSERT INTO rules (`id`,`title`,`text`,`usergroups`,`category`,`priority`,`is_active`,`icon`,`created_at`,`updated_at`,`last_updated_by`) VALUES ('12','Site Features & Usage','[list]\r\n[*]Use RSS feeds for automatic torrent updates\r\n[*]Firefox search plugin available in [url=ff.php]Tools[/url]\r\n[*]Personalize your profile with custom avatar (max 150x150)\r\n[*]Use watch lists to track favorite content\r\n[*]Enable email notifications for replies\r\n[*]Check [url=stats.php]Site Stats[/url] for latest metrics\r\n[*]Report bugs in [url=forum.php?action=viewforum&forumid=3]Bug Reports[/url]\r\n[/list]\r\n\r\n[h2]Mobile Access[/h2]\r\nFully responsive design works on all devices. No dedicated app required.','[0]','features','50','1','fa-cogs','2026-01-04 21:38:06','2026-01-04 21:38:06',NULL);
INSERT INTO rules (`id`,`title`,`text`,`usergroups`,`category`,`priority`,`is_active`,`icon`,`created_at`,`updated_at`,`last_updated_by`) VALUES ('13','Community Events & Contests','[list]\r\n[*]Participate in monthly upload contests\r\n[*]Join seasonal events for special rewards\r\n[*]Contribute to community projects\r\n[*]Suggest new event ideas in forum\r\n[*]Winners receive bonus points and special titles\r\n[*]All contests are judged fairly by staff\r\n[/list]\r\n\r\n[quote]\r\n[b]Current Event:[/b] Check Announcements forum for active contests!\r\n[/quote]','[0]','community','55','1','fa-trophy','2026-01-04 21:38:06','2026-01-04 21:38:06',NULL);
INSERT INTO rules (`id`,`title`,`text`,`usergroups`,`category`,`priority`,`is_active`,`icon`,`created_at`,`updated_at`,`last_updated_by`) VALUES ('14','Account Management Rules','[list]\r\n[*]One account per person - no multi-accounting\r\n[*]Keep email address updated for notifications\r\n[*]Inactive accounts may be pruned after 6 months\r\n[*]Account recovery requires email access\r\n[*]No username changes after registration\r\n[*]Don\'t use offensive usernames or avatars\r\n[*]Account sharing is strictly prohibited\r\n[/list]\r\n\r\n[h2]Inactivity Policy[/h2]\r\n[b]3 months:[/b] Warning email sent\r\n[b]6 months:[/b] Account marked inactive\r\n[b]1 year:[/b] Account may be deleted (VIP excluded)','[0]','account','90','1','fa-user-circle','2026-01-04 21:38:06','2026-01-04 21:38:06',NULL);
INSERT INTO rules (`id`,`title`,`text`,`usergroups`,`category`,`priority`,`is_active`,`icon`,`created_at`,`updated_at`,`last_updated_by`) VALUES ('15','Technical Requirements','[list]\r\n[*]Modern browser required (Chrome 90+, Firefox 88+, Edge 90+)\r\n[*]JavaScript must be enabled\r\n[*]Cookies required for login and ratio tracking\r\n[*]Recommended: 10 Mbps+ internet connection\r\n[*]Use proper torrent client with DHT disabled\r\n[*]Enable encryption in client settings\r\n[*]Port forwarding recommended for better speeds\r\n[/list]\r\n\r\n[h2]Recommended Clients[/h2]\r\n• qBittorrent (Cross-platform)\r\n• Deluge (Lightweight)\r\n• Transmission (Mac/Linux)\r\n• rTorrent (Advanced users)','[0]','technical','70','1','fa-laptop-code','2026-01-04 21:38:06','2026-01-04 21:38:06',NULL);
INSERT INTO rules (`id`,`title`,`text`,`usergroups`,`category`,`priority`,`is_active`,`icon`,`created_at`,`updated_at`,`last_updated_by`) VALUES ('16','Golden Rules (Most Important)','[list=1]\r\n[*][b]Respect Everyone[/b] - Treat others as you want to be treated\r\n[*][b]Seed What You Take[/b] - Keep the torrent ecosystem alive\r\n[*][b]Quality Over Quantity[/b] - Upload good content, not just any content\r\n[*][b]Read Before Asking[/b] - Check FAQ and search first\r\n[*][b]Help New Users[/b] - We were all beginners once\r\n[*][b]Report Problems[/b] - Don\'t just complain, help fix issues\r\n[*][b]Enjoy Responsibly[/b] - Have fun but follow the rules\r\n[/list]\r\n\r\n[center]\r\n[quote size=\"large\"]\r\nThe strength of the community comes from following these principles together.\r\n[/quote]\r\n[/center]','[0]','golden','100','1','fa-crown','2026-01-04 21:38:06','2026-01-04 21:38:06',NULL);
INSERT INTO rules (`id`,`title`,`text`,`usergroups`,`category`,`priority`,`is_active`,`icon`,`created_at`,`updated_at`,`last_updated_by`) VALUES ('17','Dispute Resolution Process','[list]\r\n[*]First, attempt to resolve issues directly with the user\r\n[*]If unsuccessful, contact a moderator via PM\r\n[*]Provide evidence (screenshots, links, etc.)\r\n[*]Staff will investigate and make a decision\r\n[*]All decisions are final and binding\r\n[*]No public discussion of staff decisions\r\n[*]Respect the privacy of all parties involved\r\n[/list]\r\n\r\n[alert type=\"info\"]\r\n[b]Appeals:[/b] Banned users may appeal after 30 days via email to staff@seedboxworld.biz\r\n[/alert]','[0]','dispute','80','1','fa-gavel','2026-01-04 21:38:06','2026-01-04 21:38:06',NULL);
INSERT INTO rules (`id`,`title`,`text`,`usergroups`,`category`,`priority`,`is_active`,`icon`,`created_at`,`updated_at`,`last_updated_by`) VALUES ('18','Content Categories Guide','[list]\r\n[*]Movies: Films, documentaries, short films\r\n[*]TV Shows: Series, episodes, seasons\r\n[*]Games: PC, console, mobile games\r\n[*]Software: Applications, operating systems, tools\r\n[*]Music: Albums, singles, compilations\r\n[*]Ebooks: Books, magazines, comics\r\n[*]Anime: Japanese animation series/movies\r\n[*]Other: Everything that doesn\'t fit above\r\n[/list]\r\n\r\n[h2]Category-Specific Rules[/h2]\r\n[b]Movies/TV:[/b] No camrips, proper resolution required\r\n[b]Music:[/b] Minimum 256kbps, proper metadata\r\n[b]Ebooks:[/b] No scans, proper formatting','[0]','content','65','1','fa-folder-open','2026-01-04 21:38:06','2026-01-04 21:38:06',NULL);
INSERT INTO rules (`id`,`title`,`text`,`usergroups`,`category`,`priority`,`is_active`,`icon`,`created_at`,`updated_at`,`last_updated_by`) VALUES ('19','Community Contribution Rewards','[list]\r\n[*]Submit bug reports: 50-500 points\r\n[*]Suggest useful features: 100-1000 points\r\n[*]Help in support forum: 25 points per helpful answer\r\n[*]Create tutorials/guides: 500-2000 points\r\n[*]Report rule violations: 50 points\r\n[*]Translate content: 200 points per page\r\n[*]Maintain wiki pages: 100 points weekly\r\n[/list]\r\n\r\n[center]\r\n[b]Be an active community member and earn rewards![/b]\r\n[/center]','[0]','community','60','1','fa-handshake','2026-01-04 21:38:06','2026-01-04 21:38:06',NULL);
INSERT INTO rules (`id`,`title`,`text`,`usergroups`,`category`,`priority`,`is_active`,`icon`,`created_at`,`updated_at`,`last_updated_by`) VALUES ('20','Seasonal & Special Rules','[list]\r\n[*]Holiday events may have relaxed posting rules\r\n[*]Special contests may have additional requirements\r\n[*]Site maintenance periods may affect uploads\r\n[*]Follow announcement channel for temporary changes\r\n[*]Emergency rules may be enacted during attacks\r\n[*]Beta features may have different usage rules\r\n[/list]\r\n\r\n[alert type=\"success\"]\r\nCheck the [url=announcements.php]Announcements[/url] section regularly for updates!\r\n[/alert]','[0]','seasonal','40','1','fa-calendar-alt','2026-01-04 21:38:06','2026-01-04 21:38:06',NULL);
